import{_ as t,a,b as i,c as r,d as s,e as n,f as o,g as l,h as d}from"./chunks/image-20261116060541261.BxSqcLkL.js";import{_ as c,o as g,c as h,a2 as m}from"./chunks/framework.CmPiTyN0.js";const _=JSON.parse('{"title":"Weapon Systems","description":"","frontmatter":{"title":"Weapon Systems","outline":"deep"},"headers":[],"relativePath":"en/wiki/weapons.md","filePath":"en/wiki/weapons.md","lastUpdated":1794811249000}'),p={name:"en/wiki/weapons.md"};function u(f,e,b,y,k,v){return g(),h("div",null,[...e[0]||(e[0]=[m('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_5-weapon-systems" tabindex="-1">5. Weapon Systems <a class="header-anchor" href="#_5-weapon-systems" aria-label="Permalink to &quot;5. Weapon Systems&quot;">​</a></h2><p>The RVP data directory contains 231 weapon and ammunition definition files, including subordinate entries such as warheads and submunitions. RVP vehicles generally have multiple weapon stations for the main gun, secondary guns, machine guns, missiles, and rockets. Fourteen fixed-wing and rotary-wing vehicles support custom pylons; the F/A-18F and J-16 offer the widest selection.</p><h3 id="_5-1-guns-and-ammunition" tabindex="-1">5.1 Guns and Ammunition <a class="header-anchor" href="#_5-1-guns-and-ammunition" aria-label="Permalink to &quot;5.1 Guns and Ammunition&quot;">​</a></h3><p>RVP&#39;s guns include vehicle- and aircraft-mounted machine guns, autocannons and close-in weapon systems, tank guns, naval guns, and a vehicle-mounted laser suppression system. Different weapons use different ammunition; below is a summary of the main ammunition types by their actual in-game behavior.</p><ul><li><strong>APFSDS</strong>: Fin-stabilized discarding-sabot armor-piercing round. High direct damage with no explosive payload; can penetrate 2 blocks, with direct damage falling off after passing through a wall. Effective against armored targets and highly resistant to explosive reactive armor.</li><li><strong>HEAT</strong>: Shaped-charge round. Higher direct damage plus a small explosion; the hit damage is reduced by ERA. Overall performance against both direct and explosive damage falls between APFSDS and HE. Extremely effective against lightly armored targets such as IFVs. Tank HEAT has no tandem warhead; tandem warheads are found only on missiles.</li><li><strong>HE</strong>: High-explosive round. Low direct damage, large blast damage and radius; relies on the explosion to kill soft and lightly armored targets.</li><li><strong>PELE</strong>: Penetrator with enhanced lateral effect. Lower direct damage, but releases a large number of fragments when hitting a vehicle or block; effective against light armor and infantry in enclosed spaces, limited against heavy armor.</li><li><strong>AHEAD</strong>: Programmable ammunition. Requires a radar or weapon-station lock to calculate lead and set the airburst fuze automatically. Without a lock it does not program an airburst and flies as a normal direct-fire round.</li><li><strong>Programmable airburst</strong>: Press the lock key (default <code>R</code>) to range the aim point (it must hit a block). The round detonates after traveling “measured range + offset” along its trajectory, useful for airbursts above cover or near a target.</li><li><strong>SAP</strong>: Wall-breaching high-explosive round with 1-block penetration; it can pass through a wall and detonate on a target behind it, mainly against infantry behind cover.</li><li><strong>Shotgun</strong>: Fires multiple pellets per shot, covering soft targets at close range; pellet damage falls off with distance.</li><li><strong>Railgun</strong>: ZTZ100 and AbramsX are equipped with an experimental railgun. It must be charged before firing; once fully charged, it launches a projectile at extremely high muzzle velocity.</li></ul><p><img src="'+t+'" alt="image-20261116051501338"></p><p><strong>Figure 5.1 RVP tanks carry a wide range of ammunition types for different situations.</strong></p><h3 id="_5-2-rockets" tabindex="-1">5.2 Rockets <a class="header-anchor" href="#_5-2-rockets" aria-label="Permalink to &quot;5.2 Rockets&quot;">​</a></h3><ul><li><strong>Unguided</strong>: Hydra 70, Zuni, S-13, S-8KO, FS70B, 130-2 and other rocket pods. The ballistic computer provides continuous impact calculation.</li><li><strong>Guided</strong>: APKWS, FS70A and other laser-guided rockets. They follow the laser spot and can engage moving targets.</li><li><strong>Cluster</strong>: M30, M261, FS70B cluster types. They disperse many submunitions near the ground, with strong area effects against soft targets and limited anti-armor capability.</li><li><strong>White phosphorus/incendiary</strong>: M30 white-phosphorus airburst types. They scatter a white-phosphorus barrage near the ground for large-area incendiary effect.</li></ul><p><img src="'+a+'" alt="image-20261116051856828"></p><p><strong>Figure 5.2 M142 HIMARS white-phosphorus rocket example.</strong></p><h3 id="_5-3-missiles" tabindex="-1">5.3 Missiles <a class="header-anchor" href="#_5-3-missiles" aria-label="Permalink to &quot;5.3 Missiles&quot;">​</a></h3><p>Missiles are grouped by guidance type.</p><table tabindex="0"><thead><tr><th>Guidance</th><th>Description and examples</th></tr></thead><tbody><tr><td>Infrared (IR)</td><td>Seeker tracks the target&#39;s heat signature; AIM-9M, PL-10, FIM-92K, KD-88A, etc. HMD support enables high-off-boresight acquisition, lock, and launch</td></tr><tr><td>Active radar homing (ARH)</td><td>Midcourse datalink guidance, then the onboard radar seeker activates and acquires the target; AIM-120D, PL-15, AIM-54C, YJ-19, etc.</td></tr><tr><td>Semi-active radar homing (SARH)</td><td>Requires continuous illumination from the aircraft/vehicle radar; AIM-7P, R-27R, ESSM, etc.</td></tr><tr><td>Semi-active laser homing (SALH)</td><td>A laser designates the target; the illuminated target triggers a laser warning; AGM-114K, AGM-65E, LAHAT, AKD-10, etc.</td></tr><tr><td>Laser beam riding (LBR)</td><td>Flies along a laser beam; the illuminated target triggers a laser warning; 9M119M1, GP-125, 9M127, etc.; 9M119M1 and GP-125 are gun-launched missiles</td></tr><tr><td>Anti-radiation (ARM)</td><td>Homes on an emitting radar; shutting down the radar can evade it; AGM-88E, LD-10, YJ-91, etc.</td></tr><tr><td>Active infrared (AIR)</td><td>Radar or datalink midcourse correction, then an IR seeker searches autonomously in the terminal phase; HHQ-10, HQ-13, etc.</td></tr><tr><td>GPS/INS</td><td>Satellite and inertial navigation with tactical-map designation; AKF-98A, Storm Shadow, ATACMS, YJ-20, etc. GBU-31, LS-6, and GB-3 GPS are satellite-guided bombs, covered in 5.4</td></tr><tr><td>Man-in-the-loop TV (HITL_TV)</td><td>After launch, the seeker video feed opens; the operator selects and locks a target in the feed, similar to War Thunder&#39;s man-in-the-loop missiles; KH-39, KD-88, etc.</td></tr><tr><td>Man-in-the-loop command-line TV (HITL_CLOS_TV)</td><td>After launch, the operator directly controls the missile&#39;s control surfaces to steer it, similar to Battlefield 4 TV missiles; TL-17, CM-502KG, Switchblade loitering munitions, etc.</td></tr><tr><td>SACLOS</td><td>The operator aims at the target and the missile follows the line of sight by command; harder to use than LBR but does not trigger a laser warning; TOW-2A/2B, HJ-73E, 95Ya6M, etc. TOW-2B uses an EFP top-attack warhead: it flies over the target and detonates downward, scattering fragments, effective against targets behind cover</td></tr></tbody></table><p>Some missiles have multi-mode seekers: for example, Brimstone uses a semi-active laser/active radar dual-mode seeker, flying toward the laser spot in the first phase and then activating its active radar seeker to acquire the target autonomously. Some missiles support dual-pulse motors, cold launch, high-loft/over-the-top trajectories, and proximity/impact fuzes.</p><p><img src="'+i+'" alt="image-20261116053032715"></p><p><strong>Figure 5.3 TOW-2B with an EFP top-attack warhead can hit tanks behind cover.</strong></p><p><img src="'+r+'" alt="image-20261116053553492"></p><p><strong>Figure 5.4 Anti-radiation missiles can strike emitting radar targets.</strong></p><p><img src="'+s+'" alt="image-20261116053837191"></p><p><strong>Figure 5.5 Man-in-the-loop missile (TV missile).</strong></p><h3 id="_5-4-aerial-bombs" tabindex="-1">5.4 Aerial Bombs <a class="header-anchor" href="#_5-4-aerial-bombs" aria-label="Permalink to &quot;5.4 Aerial Bombs&quot;">​</a></h3><ul><li><strong>Conventional bombs</strong>: MK-84 and similar unguided gravity bombs; the ballistic computer provides continuous impact calculation.</li><li><strong>Semi-active laser-guided bombs</strong>: GBU-24, GBU-48, GB-3 laser, GB-500, YJ-1000. Modified from conventional bombs; the carrying aircraft illuminates the laser spot and the bomb flies toward it, allowing engagement of moving targets.</li><li><strong>Satellite/inertial-guided bombs</strong>: GBU-31, LS-6, GB-3 GPS. GPS coordinates can be marked on the tactical map; after release the bomb flies toward the coordinates.</li><li><strong>Infrared-guided bombs</strong>: GB-3 IR. The IR seeker tracks target heat signatures and can engage moving targets.</li></ul><p><img src="'+n+'" alt="image-20261116055800519"></p><p><strong>Figure 5.6 Laser-guided bombs.</strong></p><h3 id="_5-5-torpedoes" tabindex="-1">5.5 Torpedoes <a class="header-anchor" href="#_5-5-torpedoes" aria-label="Permalink to &quot;5.5 Torpedoes&quot;">​</a></h3><p>Torpedoes can travel 1–2 meters below the water surface and deal massive damage to large ships.</p><p><img src="'+o+'" alt="image-20261116060112997"></p><p><strong>Figure 5.7 Torpedo launch.</strong></p><h3 id="_5-6-pods" tabindex="-1">5.6 Pods <a class="header-anchor" href="#_5-6-pods" aria-label="Permalink to &quot;5.6 Pods&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Targeting pod</td><td>Marks targets; marked targets are displayed on the tactical map.</td></tr><tr><td>Coordinate designation pod</td><td>Obtains and marks target coordinates for the GPS panel or fire support; some models integrate “call fire strike / call airstrike”</td></tr></tbody></table><p>TGP is used by the EA-18G, F/A-18F, and J-16D; EOTS by the J-20A; the SUAV pod by the light reconnaissance UAV and quadcopter reconnaissance UAV. Coordinate designation pods with integrated fire support are used by the MBT co-pilot station, EA-18G, J-16D, and reconnaissance UAVs.</p><h3 id="_5-7-laser-weapons" tabindex="-1">5.7 Laser Weapons <a class="header-anchor" href="#_5-7-laser-weapons" aria-label="Permalink to &quot;5.7 Laser Weapons&quot;">​</a></h3><ul><li>ZTZ100&#39;s 10 kW laser suppression system can illuminate enemy vehicles; after enough hits it blinds players and AI gunners.</li><li>While blinded, AI gunners can only use radar-guided or radar-midcourse weapons; players see a white screen that obstructs observation.</li><li>Laser illumination triggers the corresponding warning and HUD indication.</li></ul><h3 id="_5-8-fire-support" tabindex="-1">5.8 Fire Support <a class="header-anchor" href="#_5-8-fire-support" aria-label="Permalink to &quot;5.8 Fire Support&quot;">​</a></h3><ul><li><strong>RVP fire support terminal</strong>: Hold it in the main or off hand and right-click, or press <code>K</code> to open the fire support map; supports call, impact area, round count, and ceasefire.</li><li><strong>Fire support modes</strong>: Hasty, effective, surveillance, and aerial strike.</li><li><strong>Barrage patterns</strong>: Point, linear, and creeping barrage.</li><li><strong>Support ammunition</strong>: Aerial bombs, rockets, cluster rockets, white phosphorus, ATACMS, 9M723, GPS cruise missiles, etc., depending on the fire support configuration.</li><li><strong>Pod integration</strong>: Targeting pods can mark entities or coordinates; vehicles carrying “call fire strike”/“call airstrike” can select a strike entry in the pod interface and automatically call it after marking coordinates.</li></ul><h3 id="_5-9-weapon-customization-and-ammunition-selection" tabindex="-1">5.9 Weapon Customization and Ammunition Selection <a class="header-anchor" href="#_5-9-weapon-customization-and-ammunition-selection" aria-label="Permalink to &quot;5.9 Weapon Customization and Ammunition Selection&quot;">​</a></h3><p>Most RVP vehicles support extensive weapon customization. Players can choose different ammunition or loadouts for the mission, for example:</p><ul><li><strong>SEAD</strong>: aircraft carry anti-radiation missiles to suppress radar air-defense vehicles.</li><li><strong>DEAD</strong>: aircraft carry IR- or laser-guided missiles to strike air-defense systems with their radars off.</li><li><strong>Ground vehicles</strong>: use PELE against many lightly armored targets and APFSDS against heavy armor.</li></ul><p><img src="'+l+'" alt="image-20261116060356867"></p><p><img src="'+d+'" alt="image-20261116060541261"></p><p><strong>Figures 5.8/5.9 RVP vehicles offer extensive customization.</strong></p><hr>',44)])])}const S=c(p,[["render",u]]);export{_ as __pageData,S as default};
